#include <sqlite3.h>
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include "../../../lib/libbonfyre/include/bf_command_lookup.h"

typedef struct { char *identity,*owner; } Item;
static const char *arg(int argc,char **argv,const char *name){for(int i=2;i+1<argc;i++)if(!strcmp(argv[i],name))return argv[i+1];return NULL;}
static char *slurp(const char *path,size_t *n){FILE*f=fopen(path,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int execsql(sqlite3*d,const char*q){char*e=NULL;int rc=sqlite3_exec(d,q,NULL,NULL,&e);if(rc!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static int init(sqlite3*d){return execsql(d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS material_lease(subject TEXT NOT NULL,scope TEXT NOT NULL,identity TEXT NOT NULL,owner_ref TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(subject,scope,identity));CREATE INDEX IF NOT EXISTS material_lease_identity ON material_lease(identity);CREATE TABLE IF NOT EXISTS material_transition(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL CHECK(action IN ('acquire','release')),identity TEXT NOT NULL,owner_ref TEXT NOT NULL,refcount_before INTEGER NOT NULL,refcount_after INTEGER NOT NULL,subject TEXT NOT NULL,scope TEXT NOT NULL,created_at INTEGER NOT NULL,emitted INTEGER NOT NULL DEFAULT 0 CHECK(emitted IN (0,1)));CREATE INDEX IF NOT EXISTS material_transition_pending ON material_transition(emitted,id);");}
static void items_free(Item*a,int n){for(int i=0;i<n;i++){free(a[i].identity);free(a[i].owner);}free(a);}
static int find_item(Item*a,int n,const char*id){for(int i=0;i<n;i++)if(!strcmp(a[i].identity,id))return i;return -1;}
static int push(Item**a,int*n,const char*id,const char*owner){Item*z=realloc(*a,(size_t)(*n+1)*sizeof(**a));if(!z)return 0;*a=z;z[*n].identity=strdup(id);z[*n].owner=strdup(owner);if(!z[*n].identity||!z[*n].owner)return 0;(*n)++;return 1;}
static int lease_count(sqlite3*d,const char*id){sqlite3_stmt*s=NULL;int n=-1;if(sqlite3_prepare_v2(d,"SELECT count(*) FROM material_lease WHERE identity=?1",-1,&s,NULL)==SQLITE_OK){sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW)n=sqlite3_column_int(s,0);}sqlite3_finalize(s);return n;}
static int transition(sqlite3*d,const char*action,const Item*i,int before,int after,const char*subject,const char*scope){sqlite3_stmt*s=NULL;int ok=0;if(sqlite3_prepare_v2(d,"INSERT INTO material_transition(action,identity,owner_ref,refcount_before,refcount_after,subject,scope,created_at) VALUES(?1,?2,?3,?4,?5,?6,?7,?8)",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,action,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,i->identity,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,i->owner,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,4,before);sqlite3_bind_int(s,5,after);sqlite3_bind_text(s,6,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,7,scope,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,8,(sqlite3_int64)time(NULL));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);return ok;}
static int load_old(sqlite3*d,const char*subject,const char*scope,Item**out,int*n){sqlite3_stmt*s=NULL;if(sqlite3_prepare_v2(d,"SELECT identity,owner_ref FROM material_lease WHERE subject=?1 AND scope=?2 ORDER BY identity",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,scope,-1,SQLITE_TRANSIENT);while(sqlite3_step(s)==SQLITE_ROW)if(!push(out,n,(const char*)sqlite3_column_text(s,0),(const char*)sqlite3_column_text(s,1))){sqlite3_finalize(s);return 0;}sqlite3_finalize(s);return 1;}
static int load_current(sqlite3*address,const char*body,size_t len,Item**out,int*n){sqlite3*mem=NULL;sqlite3_stmt*q=NULL,*owner=NULL;int ok=0;if(sqlite3_open(":memory:",&mem)!=SQLITE_OK)return 0;if(sqlite3_prepare_v2(mem,"SELECT DISTINCT json_extract(c.value,'$.identity') FROM (SELECT c.value value FROM json_each(?1,'$.pack_demands') d,json_each(d.value,'$.candidate_groups') g,json_each(g.value,'$.candidates') c UNION ALL SELECT c.value FROM json_each(?1,'$.world_demands') w,json_each(w.value,'$.dependencies') dep,json_each(dep.value,'$.candidates') c) c WHERE json_extract(c.value,'$.identity') IS NOT NULL ORDER BY 1",-1,&q,NULL)!=SQLITE_OK)goto done;if(sqlite3_prepare_v2(address,"SELECT owner_ref FROM candidate_advertisement WHERE identity=?1 AND candidate_kind='external_occurrence' AND lowerer_ref='MaterialCompiler:external' AND owner_ref='ExternalEstate:'||identity",-1,&owner,NULL)!=SQLITE_OK)goto done;sqlite3_bind_text(q,1,body,(int)len,SQLITE_TRANSIENT);while(sqlite3_step(q)==SQLITE_ROW){const char*id=(const char*)sqlite3_column_text(q,0);sqlite3_bind_text(owner,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(owner)!=SQLITE_ROW||!sqlite3_column_text(owner,0))goto done;if(!push(out,n,id,(const char*)sqlite3_column_text(owner,0)))goto done;sqlite3_reset(owner);sqlite3_clear_bindings(owner);}ok=1;
done:sqlite3_finalize(q);sqlite3_finalize(owner);if(mem)sqlite3_close(mem);return ok;}
static int parse_meta(sqlite3*d,const char*body,size_t len,char**subject,char**scope){sqlite3_stmt*s=NULL;int ok=0;if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,'$.schema'),json_extract(?1,'$.truth'),json_extract(?1,'$.subject'),json_extract(?1,'$.scope')",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,body,(int)len,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW){const char*schema=(const char*)sqlite3_column_text(s,0),*truth=(const char*)sqlite3_column_text(s,1),*a=(const char*)sqlite3_column_text(s,2),*b=(const char*)sqlite3_column_text(s,3);if(schema&&!strncmp(schema,"bonfyre-scoped-demand-closure.v",30)&&truth&&!strcmp(truth,"scoped_candidate_cut_exact_owner_recheck_required")&&a&&*a&&b&&*b){*subject=strdup(a);*scope=strdup(b);ok=*subject&&*scope;}}sqlite3_finalize(s);return ok;}
static int sync_closure(sqlite3*d,sqlite3*address,const char*path){size_t len=0;char*body=slurp(path,&len),*subject=NULL,*scope=NULL;Item*old=NULL,*cur=NULL;int oldn=0,curn=0,acquired=0,released=0,ok=0;sqlite3_stmt*del=NULL,*ins=NULL;if(!body||!parse_meta(d,body,len,&subject,&scope)||!load_old(d,subject,scope,&old,&oldn)||!load_current(address,body,len,&cur,&curn)||!execsql(d,"BEGIN IMMEDIATE;"))goto done;
 for(int i=0;i<oldn;i++)if(find_item(cur,curn,old[i].identity)<0){int before=lease_count(d,old[i].identity);if(before<1||sqlite3_prepare_v2(d,"DELETE FROM material_lease WHERE subject=?1 AND scope=?2 AND identity=?3",-1,&del,NULL)!=SQLITE_OK)goto rollback;sqlite3_bind_text(del,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(del,2,scope,-1,SQLITE_TRANSIENT);sqlite3_bind_text(del,3,old[i].identity,-1,SQLITE_TRANSIENT);if(sqlite3_step(del)!=SQLITE_DONE)goto rollback;sqlite3_finalize(del);del=NULL;if(before==1){if(!transition(d,"release",&old[i],1,0,subject,scope))goto rollback;released++;}}
 for(int i=0;i<curn;i++)if(find_item(old,oldn,cur[i].identity)<0){int before=lease_count(d,cur[i].identity);if(before<0||sqlite3_prepare_v2(d,"INSERT INTO material_lease(subject,scope,identity,owner_ref,updated_at) VALUES(?1,?2,?3,?4,?5)",-1,&ins,NULL)!=SQLITE_OK)goto rollback;sqlite3_bind_text(ins,1,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(ins,2,scope,-1,SQLITE_TRANSIENT);sqlite3_bind_text(ins,3,cur[i].identity,-1,SQLITE_TRANSIENT);sqlite3_bind_text(ins,4,cur[i].owner,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(ins,5,(sqlite3_int64)time(NULL));if(sqlite3_step(ins)!=SQLITE_DONE)goto rollback;sqlite3_finalize(ins);ins=NULL;if(before==0){if(!transition(d,"acquire",&cur[i],0,1,subject,scope))goto rollback;acquired++;}}
 if(!execsql(d,"COMMIT;"))goto done;printf("{\"subject\":\"%s\",\"scope\":\"%s\",\"closure_leases\":%d,\"physical_acquires\":%d,\"physical_releases\":%d,\"truth\":\"reference_counted_material_intent_only\"}\n",subject,scope,curn,acquired,released);ok=1;goto done;
rollback:execsql(d,"ROLLBACK;");
done:sqlite3_finalize(del);sqlite3_finalize(ins);items_free(old,oldn);items_free(cur,curn);free(body);free(subject);free(scope);return ok;}
static uint64_t hash64(const char*s){uint64_t h=1469598103934665603ULL;for(const unsigned char*p=(const unsigned char*)s;*p;p++){h^=*p;h*=1099511628211ULL;}return h;}
static int mkdir_ok(const char*p){return p&&*p&&(mkdir(p,0750)==0||errno==EEXIST);}
static int emit_file(const char*dir,const char*sub,const char*name,const char*json){char folder[1200],path[1400],tmp[1440];FILE*f=NULL;if(!mkdir_ok(dir)||snprintf(folder,sizeof(folder),"%s/%s",dir,sub)>=(int)sizeof(folder)||!mkdir_ok(folder)||snprintf(path,sizeof(path),"%s/%016llx.json",folder,(unsigned long long)hash64(name))>=(int)sizeof(path))return 0;if(!access(path,F_OK))return 1;if(snprintf(tmp,sizeof(tmp),"%s.tmp",path)>=(int)sizeof(tmp)||(f=fopen(tmp,"w"))==NULL)return 0;if(fputs(json,f)<0||fputc('\n',f)==EOF||fflush(f)||fsync(fileno(f))||fclose(f)||rename(tmp,path)){if(f)fclose(f);unlink(tmp);return 0;}return 1;}
static int drain(sqlite3*d,const char*acquire,const char*cancel,int limit){sqlite3_stmt*q=NULL,*mark=NULL;int emitted=0;if(sqlite3_prepare_v2(d,"SELECT id,action,identity,owner_ref,refcount_before,refcount_after,subject,scope FROM material_transition WHERE emitted=0 ORDER BY id LIMIT ?1",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_int(q,1,limit);while(sqlite3_step(q)==SQLITE_ROW){sqlite3_int64 id=sqlite3_column_int64(q,0);const char*action=(const char*)sqlite3_column_text(q,1),*identity=(const char*)sqlite3_column_text(q,2),*owner=(const char*)sqlite3_column_text(q,3),*subject=(const char*)sqlite3_column_text(q,6),*scope=(const char*)sqlite3_column_text(q,7);char name[1400],json[4096];int before=sqlite3_column_int(q,4),after=sqlite3_column_int(q,5),ok;if(snprintf(name,sizeof(name),"%s:%lld",identity,(long long)id)>=(int)sizeof(name))goto fail;if(!strcmp(action,"acquire")){if(!acquire)return 0;snprintf(json,sizeof(json),"{\"schema\":\"bonfyre-lowering-handoff.v1\",\"delta_id\":\"material-lease:%lld\",\"identity\":\"%s\",\"candidate_kind\":\"external_occurrence\",\"owner_ref\":\"%s\",\"lowerer_ref\":\"MaterialCompiler:external\",\"truth\":\"dependency_cut_only\"}",(long long)id,identity,owner);ok=emit_file(acquire,"MaterialCompiler-external",name,json);}else{if(!cancel)return 0;snprintf(json,sizeof(json),"{\"schema\":\"bonfyre-material-observation-cancel.v1\",\"transition_id\":%lld,\"identity\":\"%s\",\"refcount_before\":%d,\"refcount_after\":%d,\"released_by\":{\"subject\":\"%s\",\"scope\":\"%s\"},\"truth\":\"lease_count_zero_not_observation_retraction\"}",(long long)id,identity,before,after,subject,scope);ok=emit_file(cancel,"MaterialCompiler-external",name,json);}if(!ok)goto fail;if(sqlite3_prepare_v2(d,"UPDATE material_transition SET emitted=1 WHERE id=?1 AND emitted=0",-1,&mark,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_int64(mark,1,id);if(sqlite3_step(mark)!=SQLITE_DONE||sqlite3_changes(d)!=1)goto fail;sqlite3_finalize(mark);mark=NULL;emitted++;}sqlite3_finalize(q);printf("{\"transitions_emitted\":%d,\"truth\":\"physical_work_boundary_only\"}\n",emitted);return 1;
fail:sqlite3_finalize(q);sqlite3_finalize(mark);return 0;}
int main(int argc,char**argv){const char*dbp=arg(argc,argv,"--db");sqlite3*d=NULL,*address=NULL;int ok=0;if(argc<2||!dbp){fputs("usage: bonfyre-material-lease sync --db DB --address-db DB --closure JSON | drain --db DB --acquire-dir DIR --cancel-dir DIR [--limit N]\n",stderr);return 2;}if(sqlite3_open(dbp,&d)!=SQLITE_OK||!init(d))goto out;enum{ML_DRAIN,ML_SYNC};static const BfCommandEntry lease_commands[]={{"drain",ML_DRAIN,0,NULL},{"sync",ML_SYNC,0,NULL},};const BfCommandEntry*command=bf_command_lookup(lease_commands,sizeof(lease_commands)/sizeof(lease_commands[0]),argv[1]);if(command&&command->id==ML_SYNC){const char*a=arg(argc,argv,"--address-db"),*c=arg(argc,argv,"--closure");if(!a||!c||sqlite3_open_v2(a,&address,SQLITE_OPEN_READONLY,NULL)!=SQLITE_OK)goto out;ok=sync_closure(d,address,c);}else if(command&&command->id==ML_DRAIN){int limit=arg(argc,argv,"--limit")?atoi(arg(argc,argv,"--limit")):256;if(limit<1)limit=1;if(limit>4096)limit=4096;ok=drain(d,arg(argc,argv,"--acquire-dir"),arg(argc,argv,"--cancel-dir"),limit);}else fputs("unknown command\n",stderr);
out:if(address)sqlite3_close(address);if(d)sqlite3_close(d);return ok?0:1;}
